# AV1 OBU header format:
# bit 7: forbidden_bit (0)
# bits 6-3: obu_type (4 bits)
# bit 2: obu_extension_flag
# bit 1: obu_has_size_field
# bit 0: reserved_1bit (0)
# If extension flag: 8 more bits
# If has_size: LEB128 encoded size

with open('/tmp/soccer_cif_20f_q48.ivf', 'rb') as f:
    data = f.read()

frame_hdr_start = 32
frame_sz = int.from_bytes(data[frame_hdr_start:frame_hdr_start+4], 'little')
frame = data[frame_hdr_start+12:frame_hdr_start+12+frame_sz]

OBU_TYPES = {
    1: 'SEQUENCE_HEADER',
    2: 'TEMPORAL_DELIMITER',
    3: 'FRAME_HEADER',
    4: 'TILE_GROUP',
    5: 'METADATA',
    6: 'FRAME',
    7: 'REDUNDANT_FRAME_HEADER',
    8: 'TILE_LIST',
    15: 'PADDING',
}

pos = 0
while pos < len(frame):
    hdr = frame[pos]
    forbidden = (hdr >> 7) & 1
    obu_type = (hdr >> 3) & 0xF
    ext_flag = (hdr >> 2) & 1
    has_size = (hdr >> 1) & 1
    pos += 1
    if ext_flag:
        pos += 1  # extension header
    # LEB128 size
    size = 0
    shift = 0
    if has_size:
