    1: 'SEQUENCE_HEADER',
    2: 'TEMPORAL_DELIMITER',
    3: 'FRAME_HEADER',
    4: 'TILE_GROUP',
    5: 'METADATA',
    6: 'FRAME',
    7: 'REDUNDANT_FRAME_HEADER',
    8: 'TILE_LIST',
    15: 'PADDING',
}

